@page "/settings"
@using sv_f4acd0cdbad84d66940854815ee52646.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">Loading…</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

@* ──────── Profile Section ──────── *@
@{ RenderFragment RenderProfile() =>
    @<section class="settings-section">
        <h2>Profile</h2>
        <div class="avatar-area">
            <img src="@_profileDisplayName" alt="avatar" class="avatar-preview"
                 onerror="this.style.display='none'" />
            @* Show URL below *@
            <p class="avatar-url-display">@_profileAvatarUrl</p>
        </div>
        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="_profileDisplayName" @bind:event="oninput" class="form-control" />
        </div>
        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="_profileEmail" @bind:event="oninput" class="form-control" />
        </div>
        <div class="form-group">
            <label>Avatar URL</label>
            <input type="url" @bind="_profileAvatarUrl" @bind:event="oninput" class="form-control" />
        </div>
        <div class="form-group">
            <label>Bio</label>
            <textarea @bind="_profileBio" @bind:event="oninput" class="form-control" rows="4"></textarea>
        </div>
        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </section>;
}

@* ──────── Notifications Section ──────── *@
@{ RenderFragment RenderNotifications() =>
    @<section class="settings-section">
        <h2>Notifications</h2>
        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="_notifEmail" class="toggle-switch" />
            </label>
            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="_notifPush" class="toggle-switch" />
            </label>
            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="_notifWeeklyDigest" class="toggle-switch" />
            </label>
        </div>
        <h4>Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var ch = channel;
                <label class="channel-item">
                    <input type="checkbox" checked="@_mutedChannels.Contains(ch)"
                           @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                    <span>#@ch</span>
                </label>
            }
        </div>
        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>;
}

@* ──────── Security Section ──────── *@
@{ RenderFragment RenderSecurity() =>
    @<section class="settings-section">
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-toggle" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                @(_passwordPanelOpen ? "▾" : "▸") Change Password
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label>Current Password</label>
                        <input type="password" @bind="_currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>New Password</label>
                        <input type="password" @bind="_newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label>Confirm New Password</label>
                        <input type="password" @bind="_confirmPassword" class="form-control" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="toggle-row">
            <span>
                Two-Factor Authentication
                <span class="status-badge @(_twoFactorEnabled ? "badge-on" : "badge-off")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </span>
            <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-switch" />
        </div>

        @if (_securityLastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @_securityLastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h4>Active Sessions</h4>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != _currentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>

        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="() => _sessionToRevoke = null">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="button-row">
                        <button class="btn btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                        <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>;
}

@* ──────── Appearance Section ──────── *@
@{ RenderFragment RenderAppearance() =>
    @<section class="settings-section">
        <h2>Appearance</h2>

        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    var t = theme;
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@t" checked="@(_appearanceTheme == t)"
                               @onchange="() => _appearanceTheme = t" />
                        @t
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var s = size;
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@s" checked="@(_appearanceFontSize == s)"
                               @onchange="() => _appearanceFontSize = s" />
                        @s
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label><strong>Language</strong></label>
            <select @bind="_appearanceLanguage" class="form-control">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <label class="toggle-row">
            <span><strong>Compact Mode</strong></span>
            <input type="checkbox" @bind="_appearanceCompactMode" class="toggle-switch" />
        </label>

        <h4>Live Preview</h4>
        <div class="live-preview @GetPreviewClasses()">
            <p class="preview-heading">Dashboard Overview</p>
            <p>This is a preview of how your selected appearance settings will look. The theme, font size, and compact mode are reflected here.</p>
            <div class="preview-card">
                <span class="preview-label">Card Element</span>
                <span>Sample content in a card.</span>
            </div>
        </div>

        <div class="button-row">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>;
}

@code {
    // ── Section navigation ──
    private string ActiveSection { get; set; } = "profile";

    private record SectionDef(string Key, string Label, string Icon);
    private static readonly SectionDef[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];

    private bool _loading = true;

    // ── Toast ──
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // ── Notification state ──
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private HashSet<string> _mutedChannels = [];
    private readonly List<string> _allChannels = InMemorySettingsService.AllChannels;

    // ── Security state ──
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _securityLastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private ActiveSession? _sessionToRevoke;
    private readonly string _currentSessionId = "sess-1";

    // ── Appearance state ──
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var secTask = SettingsService.GetSecuritySettingsAsync();
        var appTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, secTask, appTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;

        var notif = notifTask.Result;
        _notifEmail = notif.EmailNotifications;
        _notifPush = notif.PushNotifications;
        _notifWeeklyDigest = notif.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        var sec = secTask.Result;
        _twoFactorEnabled = sec.TwoFactorEnabled;
        _securityLastPasswordChange = sec.LastPasswordChange;
        _sessions = sec.Sessions.ToList();

        var app = appTask.Result;
        _appearanceTheme = app.Theme;
        _appearanceFontSize = app.FontSize;
        _appearanceLanguage = app.Language;
        _appearanceCompactMode = app.CompactMode;
    }

    // ── Toast helper ──
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ── Profile actions ──
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _profileDisplayName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
        _profileBio = _savedProfile.Bio;
    }

    // ── Notification actions ──
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ── Security actions ──
    private async Task UpdatePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match.", isError: true);
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _securityLastPasswordChange = DateTime.UtcNow;
            _passwordPanelOpen = false;
            await ShowToast("Password updated successfully!");
        }
        catch (ArgumentException ex)
        {
            await ShowToast(ex.Message, isError: true);
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance actions ──
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appearanceTheme.ToLowerInvariant()} preview-font-{_appearanceFontSize.ToLowerInvariant()}";
        if (_appearanceCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }
}

/* ═══════════ Settings Dashboard Layout ═══════════ */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    gap: 0;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.sidebar-nav {
    list-style: none;
    padding: 0.5rem 0 0;
    margin: 0;
}

.sidebar-nav li {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.7rem 1.25rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #495057;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
}

.sidebar-nav li:hover {
    background: #e9ecef;
}

.sidebar-nav li.active {
    background: #e7f1ff;
    border-left-color: #0d6efd;
    color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content area ── */

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #212529;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.settings-section h4 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.05rem;
    font-weight: 600;
    color: #495057;
}

/* ── Form elements ── */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #495057;
    font-size: 0.9rem;
}

.form-control {
    display: block;
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: none;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

select.form-control {
    max-width: 280px;
}

/* ── Buttons ── */

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    border: 1px solid transparent;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s, box-shadow 0.15s;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #fff;
    color: #495057;
    border-color: #ced4da;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* ── Avatar ── */

.avatar-area {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
    background: #e9ecef;
}

.avatar-url-display {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* ── Toggle rows ── */

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.65rem 0.85rem;
    background: #f8f9fa;
    border-radius: 8px;
    cursor: pointer;
    margin-bottom: 0.4rem;
}

.toggle-row span {
    font-size: 0.95rem;
}

.toggle-switch {
    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: #0d6efd;
}

/* ── Channel list ── */

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.6rem;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f0f0f0;
}

.channel-item input[type="checkbox"] {
    accent-color: #0d6efd;
}

/* ── Expandable panel ── */

.expandable-panel {
    margin-bottom: 1.25rem;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
}

.panel-toggle {
    display: block;
    width: 100%;
    background: #f8f9fa;
    border: none;
    padding: 0.75rem 1rem;
    font-size: 1rem;
    font-weight: 500;
    text-align: left;
    cursor: pointer;
    color: #212529;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* ── Status badges ── */

.status-badge {
    display: inline-block;
    padding: 0.15rem 0.55rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-left: 0.5rem;
    vertical-align: middle;
}

.badge-on {
    background: #d1e7dd;
    color: #0f5132;
}

.badge-off {
    background: #f8d7da;
    color: #842029;
}

.current-badge {
    font-size: 0.8rem;
    color: #6c757d;
    font-style: italic;
}

.info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin: 0.5rem 0 1rem;
}

/* ── Sessions table ── */

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.65rem 0.85rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #495057;
}

.sessions-table tr:hover td {
    background: #f8f9fa;
}

/* ── Radio groups ── */

.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-item input[type="radio"] {
