    flex-direction: column;
    gap: 0.25rem;
    margin-top: 0.75rem;
    padding: 0.75rem;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.preview-label {
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

/* Preview themes */
.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-theme-dark .preview-card {
