    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #212529;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

